	if completedAt.Valid {
		t, err := parseTime(completedAt.String)
		if err != nil {
			return RelayJob{}, fmt.Errorf("completed_at: %w", err)
		}
		job.CompletedAt = t
	}
	job.Consumed = consumed == 1
	return job, nil
